contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address callee, bytes memory _data) public {
        bool reverted = false;
        (bool s,) = address(c).call(abi.encodeWithSignature("forward(address,bytes)", callee, _data));
        assembly { reverted := iszero(s) }
        (bool ok,) = callee.call(_data);
        assert(!ok || !reverted);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint gasLimit) public payable {
        require(true);
        bytes memory data = abi.encodeWithSignature("revertWithInsufficientGas()");
        bool reverted;
        try c.forward{gas: gasLimit}(address(this), data) { reverted = false; } catch { reverted = true; }
        assert(reverted == true);
    }
    receive() external payable {
        // The fallback function that consumes all gas and reverts
        while (gasleft() > 0) {}
        revert("Insufficient gas to complete");
    }
}

